js=js.replace("init().catch(e=>{window.error=e.stack;throw e});",'''let pending=false;function update(){if(!window.ready||pending)return;pending=true;requestAnimationFrame(async()=>{try{const yaw=Number(document.getElementById('yaw').value)*Math.PI/180;const zoom=Number(document.getElementById('zoom').value);const mode=document.getElementById('mode').value;const width=Math.min(1200,innerWidth),height=Math.min(1100,innerHeight-125);let target=[44,112,44],spanZ=242/zoom,rise=38,dist=340,extra={};if(mode==='lower'){target=[44,45,44];spanZ=65/zoom;rise=25;dist=180}if(mode==='upper'){target=[44,127,44];spanZ=40/zoom;rise=25;dist=180}if(mode==='section'){target=[44,46,44];spanZ=44/zoom;rise=12;extra.cutX=44}let eye=[44+Math.sin(yaw)*dist,target[1]+rise,44+Math.cos(yaw)*dist];if(mode==='top'){target=[44,3,44];eye=[44,500,44];spanZ=92/zoom}await window.render({width,height,spanZ,spanX:spanZ*width/height,eye,target,ortho:true,night:document.getElementById('night').checked,concept:false,...extra});document.getElementById('msg').textContent='NBT 同源几何 · 拖动旋转 · 玻璃及照明为近似预览';}catch(e){window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message}pending=false})}
for(const el of document.querySelectorAll('input,select'))el.addEventListener('input',update);let drag=null;cv.addEventListener('pointerdown',e=>{drag=[e.clientX,Number(document.getElementById('yaw').value)];cv.setPointerCapture(e.pointerId)});cv.addEventListener('pointermove',e=>{if(drag){document.getElementById('yaw').value=(drag[1]+(e.clientX-drag[0])*.5+720)%360;update()}});cv.addEventListener('pointerup',()=>drag=null);window.addEventListener('resize',update);init().then(update).catch(e=>{window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message});''')
